    def check_auth_status(self) -> dict:
        """Check if Claude CLI is authenticated."""
        try:
            result = subprocess.run(
                ['claude', '--version'],  # Or appropriate status command
                capture_output=True,
                text=True,
                timeout=10
            )
            # Check for OAuth token file
            token_path = Path.home() / '.claude' / 'token.json'
            if token_path.exists():
                token_data = json.loads(token_path.read_text())
                # Check expiry if available
                return {'status': 'authenticated', 'token_path': str(token_path)}
            return {'status': 'not_authenticated'}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}

    def _call_claude(self, prompt: str) -> str:
        """Execute claude CLI with auth check."""
        auth = self.check_auth_status()
        if auth['status'] != 'authenticated':
            raise ClaudeAuthError(
                "Claude CLI not authenticated. Run 'claude login' on the server."
            )
