import subprocess
from pathlib import Path

class CaptionGenerator:
    # ... existing code ...

    def check_oauth_health(self) -> tuple[bool, str]:
        """Check if Claude OAuth token is valid."""
        try:
            result = subprocess.run(
                ["claude", "-p", "Say 'OK'"],
                capture_output=True, text=True, timeout=30
            )
            if result.returncode == 0 and "OK" in result.stdout:
                return True, "OAuth token valid"
            elif "not authenticated" in result.stderr.lower():
                return False, "OAuth token expired - run 'claude login'"
            else:
                return False, f"Unknown error: {result.stderr}"
        except subprocess.TimeoutExpired:
            return False, "Claude CLI timeout"
        except Exception as e:
            return False, str(e)
